mapper.select:
SELECT p.PRODUCT_NO, p.PRODUCT_NAME, p.PRODUCT_PRICE, p.BRAND, f.FILE_NAME FROM PRODUCT p
LEFT JOIN PRODUCT_FILE f ON p.PRODUCT_NO = f.PRODUCT_NO AND f.IS_MAIN = 'Y' WHERE p.PRODUCT_STATUS = 'Y'
AND p.A_SUB_NO = #{aSubNo}
AND p.I_SUB_NO = #{iSubNo}
AND p.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%')
ORDER BY p.PRODUCT_NO DESC
